import fitz, numpy as np
doc = fitz.open('eprint/modifiedVULFexclusionCombined2CORRECTED2.pdf')
page = doc[0]

# calibration
def X(px): return -22 + (px-33.95)/((236.8-33.95)/9)
def Y(py): return -6 + (119.85-py)/((119.85-11.8)/5)

def collect(colmatch):
    segs=[]
    for d in page.get_drawings():
        col=d.get('color')
        if col is None: continue
        if colmatch(col) and d['type']=='s':
            pts=[]
            for it in d['items']:
                if it[0]=='l':
                    pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
                elif it[0]=='c':
                    for p in it[1:]:
                        pts.append((p.x,p.y))
            segs.append(pts)
    return segs

green = collect(lambda c: abs(c[0])<0.01 and abs(c[1]-0.667)<0.02 and abs(c[2])<0.01)
gray  = collect(lambda c: all(abs(x-0.5)<0.01 for x in c))
black = collect(lambda c: all(abs(x)<0.01 for x in c))
for name,segs in [('green',green),('gray',gray),('black',black)]:
    print(name, 'nsegs:', len(segs), 'sizes:', [len(s) for s in segs][:10])

# black segments detail
for s in black:
    a=np.array(s)
    print('black seg x range', a[:,0].min(), a[:,0].max(), 'y range', a[:,1].min(), a[:,1].max(), 'n', len(s))
