import fitz, numpy as np
doc = fitz.open('eprint/modifiedVULFexclusionCombined2CORRECTED2.pdf')
page = doc[0]
def X(px): return -22 + (px-33.941)/22.53778
def Y(py): return -6 + (119.129-py)/21.61407

segs=[]
for d in page.get_drawings():
    col=d.get('color')
    if col and abs(col[0])<0.01 and abs(col[1]-0.667)<0.02 and abs(col[2])<0.01 and d['type']=='s':
        pts=[]
        for it in d['items']:
            if it[0]=='l':
                if not pts or (pts[-1]!=(it[1].x,it[1].y)): pts.append((it[1].x,it[1].y))
                pts.append((it[2].x,it[2].y))
            elif it[0]=='c':
                for p in it[1:]: pts.append((p.x,p.y))
        segs.append(np.array(pts))
for s in segs:
    print('seg n=%d, xstart %.2f xend %.2f, x range [%.2f, %.2f], y range [%.2f, %.2f]'%(
        len(s), s[0,0], s[-1,0], s[:,0].min(), s[:,0].max(), s[:,1].min(), s[:,1].max()))
    print('  start', s[0], 'end', s[-1])
